head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.jFilter = ''; // 전체, 성공, 실패, 우편함
scwin.allCnt = 0;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";
        // MxDataSet_code1.reset();
        const sbmOptions = {
            id : "sbm_MxDataSet",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_mdsDel",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "mdsDel=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // fn_code1_sync();
        $c.cm.PanelToGroupBox_01(panel_1);
        // PanelToGroupBox_02(panel_2);
        toDaySet(txb_date);
        MxDataSet.UseFilter = "true";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT10200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10200.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description btn_cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_cal_onclick = function() {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10200.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sys_search_onclick = async function() {
    try {
        if (txb_date.getValue() !== "") {
            await scwin.listSync(); // alert();

        } else {
            await $c.win.alert("일자를 지정하십시요");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT10200.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toExcel_onclick = function() {
    try {
        $c.data.downloadGridViewExcel(MxGrid_1, {fileName: "지분추출현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10200.btn_toExcel_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_OnFilter
 * @description Mx Data Set On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_OnFilter = function(row) {
    try {
        if (scwin.jFilter === '') {
            scwin.allCnt++;
            return true;
        } else {
            if (MxDataSet.getCellData(row, "SUC_GUBN") === scwin.jFilter) {
                scwin.allCnt++;
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10200.MxDataSet_OnFilter" });
    }
};

/**
 * @method
 * @name MxComResult_onselchange
 * @description MxComResult onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.MxComResult_onselchange = function() {
    try {
        scwin.allCnt = 0;
        scwin.jFilter = MxComResult.BindColVal;
        if (scwin.jFilter === '전체') scwin.jFilter = '';
        MxDataSet.Filter();
        scwin.setCountBox();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10200.MxComResult_onselchange" });
    }
};

/**
 * @method
 * @name MxGrid_1_onlbuttondblclk
 * @description MxGrid_1 onlbuttondblclk 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} xpos xpos
 * @param {*} ypos ypos
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxGrid_1_onlbuttondblclk = async function(row, colid, xpos, ypos) {
    try {
        if (colid === 'SUC_GUBN' && row <= MxDataSet.getRowCount() && row > 0) {
            if (MxDataSet.getCellData(MxDataSet.getRowPosition(), "SUC_GUBN") === '실패') await scwin.doDelete(MxDataSet.getCellData(MxDataSet.getRowPosition(), "FORM_CD"), MxDataSet.getCellData(MxDataSet.getRowPosition(), "ACPT_NO"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT10200.MxGrid_1_onlbuttondblclk" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
