/**
 * @method
 * @name doDelete
 * @description do Delete 처리
 * @param {*} form_cd form_cd
 * @param {*} acpt_no acpt_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doDelete = async function(form_cd, acpt_no) {
    const param = "FORM_CD=" + form_cd + ",ACPT_NO=" + acpt_no;
    await $c.win.alert(acpt_no + ":" + param);
    trDel.KeyName = "toinb_dataid4";
    // [전환검토] trDel.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    // };
    const sbmOptions = {
        id : "sbm_trDel",
        action : "/shrextrc.do",
        ref : "MxDataSet",
        target : "trDel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name doDelete1
 * @description do Delete1 처리
 * @param {*} form_cd form_cd
 * @param {*} acpt_no acpt_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doDelete1 = async function(form_cd, acpt_no) {
    await $c.win.alert(acpt_no);
    mdsDel.removeAll();
    mdsDel.insertRow();
    mdsDel.setCellData(mdsDel.getRowPosition(), "FORM_CD", form_cd);
    mdsDel.setCellData(mdsDel.getRowPosition(), "ACPT_NO", acpt_no);
    trDel.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trDel",
        action : "/shrextrc.do",
        ref : "mdsDel",
        target : "trDel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCountBox
 * @description set Count Box 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCountBox = function() {
    textbox_1.setValue("총 " + scwin.allCnt + "건");
};
